function spClone(v){return JSON.parse(JSON.stringify(v));}
function specialPageMeta(p){if(!p||!SPECIAL_PAGE_DEFAULTS[p.slug])return null;p.meta=deepFill(p.meta||{},SPECIAL_PAGE_DEFAULTS[p.slug]);return p.meta;}
function spTriples(v){return parseTripleLines(v);}
function spTripleText(a){return tripleLines(a||[]);}
function spField(label,name,value,hint=''){return `<div class="field"><label>${esc(label)}</label><input class="inp" name="${esc(name)}" value="${esc(value||'')}">${hint?`<small class="hint">${esc(hint)}</small>`:''}</div>`;}
function spText(label,name,value,hint=''){return `<div class="field"><label>${esc(label)}</label><textarea class="inp" name="${esc(name)}" style="min-height:88px">${esc(value||'')}</textarea>${hint?`<small class="hint">${esc(hint)}</small>`:''}</div>`;}
function specialPageFields(slug,m){
  if(slug==='story')return `<div class="media-guide-note"><b>Designed Our Story page:</b> these fields feed the current approved layout; the layout itself is unchanged.</div>
    ${spField('Hero kicker','spKicker',m.kicker)}${spField('Hero title','spTitle',m.title)}${spText('Hero description','spSub',m.sub)}
    <div class="row2">${spField('Primary button text','spPrimaryText',m.primaryText)}${spField('Primary button link','spPrimaryLink',m.primaryLink)}</div>
    <div class="row2">${spField('Secondary button text','spSecondaryText',m.secondaryText)}${spField('Secondary button link','spSecondaryLink',m.secondaryLink)}</div>
    ${spText('Hero facts','spFacts',spTripleText(m.facts),'Format: icon|text|optional note.')}${spField('Hero note title','spNoteTitle',m.noteTitle)}${spText('Hero note text','spNoteText',m.noteText)}
    ${spText('Trust items','spTrust',spTripleText(m.trust),'Format: icon|title|description.')}${spField('Intro label','spIntroLabel',m.introLabel)}${spField('Intro title','spIntroTitle',m.introTitle)}${spText('Intro closing paragraph','spIntroExtra',m.introExtra)}
    ${spField('Journey label','spJourneyLabel',m.journeyLabel)}${spField('Journey title','spJourneyTitle',m.journeyTitle)}${spText('Journey description','spJourneySub',m.journeySub)}${spText('Journey steps','spSteps',spTripleText(m.steps),'Format: icon|title|description.')}
    ${spField('Values label','spValuesLabel',m.valuesLabel)}${spField('Values title','spValuesTitle',m.valuesTitle)}${spText('Value cards','spValues',spTripleText(m.values),'Format: icon|title|description.')}
    ${spField('Explore label','spExploreLabel',m.exploreLabel)}${spField('Explore title','spExploreTitle',m.exploreTitle)}${spText('Explore description','spExploreSub',m.exploreSub)}${spField('Explore link text','spExploreLinkText',m.exploreLinkText)}
    ${spText('Quote','spQuote',m.quote)}${spField('Quote byline','spQuoteBy',m.quoteBy)}${spField('Bottom CTA title','spBottomTitle',m.bottomTitle)}${spText('Bottom CTA description','spBottomSub',m.bottomSub)}
    <div class="row2">${spField('Bottom primary text','spBottomPrimaryText',m.bottomPrimaryText)}${spField('Bottom primary link','spBottomPrimaryLink',m.bottomPrimaryLink)}</div><div class="row2">${spField('Bottom secondary text','spBottomSecondaryText',m.bottomSecondaryText)}${spField('Bottom secondary link','spBottomSecondaryLink',m.bottomSecondaryLink)}</div>`;
  if(slug==='returns')return `<div class="media-guide-note"><b>Designed Returns page:</b> edit the content below without changing the current visual layout. The main Content box above is used for the 7-day guarantee paragraph.</div>
    ${spField('Hero kicker','spKicker',m.kicker)}${spField('Hero title','spTitle',m.title)}${spText('Hero description','spSub',m.sub)}${spText('Hero badges','spBadges',spTripleText(m.badges),'Format: icon|text|optional note.')}
    ${spField('Guarantee card title','spGuaranteeTitle',m.guaranteeTitle)}${spField('Process heading','spProcessTitle',m.processTitle)}${spText('Process steps','spSteps',spTripleText(m.steps),'Format: icon|title|description.')}${spText('Coverage cards','spFeatures',spTripleText(m.features),'Format: icon|title|description.')}
    ${spField('Before-request heading','spBeforeTitle',m.beforeTitle)}${spText('Before-request text','spBeforeText',m.beforeText)}${spText('Before-request note','spBeforeNote',m.beforeNote)}
    ${spField('Bottom CTA title','spCtaTitle',m.ctaTitle)}${spText('Bottom CTA description','spCtaSub',m.ctaSub)}<div class="row2">${spField('CTA button text','spCtaText',m.ctaText)}${spField('CTA button link','spCtaLink',m.ctaLink)}</div>`;
  if(slug==='contact')return `<div class="media-guide-note"><b>Designed Contact page:</b> phone, email and address still come from Website Settings; these fields control the surrounding labels/copy only.</div>
    ${spField('Hero kicker','spKicker',m.kicker)}${spField('Hero title','spTitle',m.title)}${spText('Hero description','spSub',m.sub)}<div class="row2">${spField('Location badge','spLocationBadge',m.locationBadge)}${spField('Opening hours','spHours',m.hours)}</div>
    <div class="row2">${spField('Call card title','spCallTitle',m.callTitle)}${spField('Call card note','spCallNote',m.callNote)}</div><div class="row2">${spField('Email card title','spEmailTitle',m.emailTitle)}${spField('Email card note','spEmailNote',m.emailNote)}</div>
    <div class="row2">${spField('WhatsApp card title','spWhatsappTitle',m.whatsappTitle)}${spField('WhatsApp link text','spWhatsappText',m.whatsappText)}</div>${spText('WhatsApp note','spWhatsappNote',m.whatsappNote)}<div class="row2">${spField('Nursery card title','spNurseryTitle',m.nurseryTitle)}${spField('Nursery note','spNurseryNote',m.nurseryNote)}</div>
    ${spField('Form heading','spFormTitle',m.formTitle)}${spText('Form description','spFormSub',m.formSub)}${spField('Message placeholder','spFormPlaceholder',m.formPlaceholder)}${spText('Form security note','spSecurityNote',m.securityNote)}
    ${spField('Help section heading','spHelpTitle',m.helpTitle)}${spText('Help cards','spHelp',spTripleText(m.help),'Format: icon|title|description.')}
    ${spField('Bottom CTA title','spCtaTitle',m.ctaTitle)}${spText('Bottom CTA description','spCtaSub',m.ctaSub)}<div class="row2">${spField('CTA button text','spCtaText',m.ctaText)}${spField('CTA button link','spCtaLink',m.ctaLink)}</div>
    ${spField('Sidebar heading','spAsideTitle',m.asideTitle)}${spText('Sidebar text','spAsideText',m.asideText)}`;
  return '';
}

/* Override only the page editor: existing Pages UI and routes stay unchanged. */
function pageForm(id){
  const p=id==='new'?{id:'',title:'',slug:'',body:'',active:true,seoTitle:'',seoDesc:'',meta:null}:DB.pages.find(x=>x.id===id); if(!p)return;
  const special=!!SPECIAL_PAGE_DEFAULTS[p.slug],m=special?specialPageMeta(p):null;
  openModal(id==='new'?'Add page':'Edit page',`<form id="pgForm" novalidate>
    <div class="field"><label>Title</label><input class="inp" name="title" data-v="text" data-label="Title" value="${esc(p.title)}"></div>
    <div class="field"><label>Address</label><input class="inp" name="slug" data-v="slug" data-label="Address" value="${esc(p.slug)}" placeholder="about" ${special?'readonly':''}>${special?'<small class="hint">Built-in designed page address is locked so existing links do not break.</small>':''}</div>
    <div class="field"><label>Content</label><textarea class="inp" name="body" data-v="msg" data-label="Content" style="min-height:150px">${esc(p.body||'')}</textarea>${special?'<small class="hint">This remains part of the designed page and is not discarded.</small>':''}</div>
    <div class="row2">${spField('SEO title (optional)','seoTitle',p.seoTitle||'')}${spField('SEO description (optional)','seoDesc',p.seoDesc||'')}</div>
    ${specialPageFields(p.slug,m)}
    <label style="display:flex;gap:8px;align-items:center;font-size:13.5px"><input type="checkbox" name="active" ${p.active?'checked':''}> Live on website</label>
    <input type="hidden" name="id" value="${esc(p.id)}"></form>`,
    `<button class="btn btn-line btn-sq" data-close="1">Cancel</button><button class="btn btn-primary btn-sq" id="pgSave">Save page</button>`);
  $('#pgSave').onclick=()=>{const f=$('#pgForm');if(!validateForm(f))return;const d=Object.fromEntries(new FormData(f).entries());const slug=String(d.slug||'').trim();
    const obj={id:d.id||uid('pg'),title:d.title,slug,body:d.body,active:!!d.active,seoTitle:(d.seoTitle||'').trim(),seoDesc:(d.seoDesc||'').trim()};
    if(SPECIAL_PAGE_DEFAULTS[slug]){const mm=specialPageMeta(p)||spClone(SPECIAL_PAGE_DEFAULTS[slug]);
      if(slug==='story')Object.assign(mm,{kicker:d.spKicker,title:d.spTitle,sub:d.spSub,primaryText:d.spPrimaryText,primaryLink:d.spPrimaryLink,secondaryText:d.spSecondaryText,secondaryLink:d.spSecondaryLink,noteTitle:d.spNoteTitle,noteText:d.spNoteText,introLabel:d.spIntroLabel,introTitle:d.spIntroTitle,introExtra:d.spIntroExtra,journeyLabel:d.spJourneyLabel,journeyTitle:d.spJourneyTitle,journeySub:d.spJourneySub,valuesLabel:d.spValuesLabel,valuesTitle:d.spValuesTitle,exploreLabel:d.spExploreLabel,exploreTitle:d.spExploreTitle,exploreSub:d.spExploreSub,exploreLinkText:d.spExploreLinkText,quote:d.spQuote,quoteBy:d.spQuoteBy,bottomTitle:d.spBottomTitle,bottomSub:d.spBottomSub,bottomPrimaryText:d.spBottomPrimaryText,bottomPrimaryLink:d.spBottomPrimaryLink,bottomSecondaryText:d.spBottomSecondaryText,bottomSecondaryLink:d.spBottomSecondaryLink});
      if(slug==='story'){const a=spTriples(d.spFacts);if(a.length)mm.facts=a;const b=spTriples(d.spTrust);if(b.length)mm.trust=b;const c=spTriples(d.spSteps);if(c.length)mm.steps=c;const v=spTriples(d.spValues);if(v.length)mm.values=v;}
      if(slug==='returns'){Object.assign(mm,{kicker:d.spKicker,title:d.spTitle,sub:d.spSub,guaranteeTitle:d.spGuaranteeTitle,processTitle:d.spProcessTitle,beforeTitle:d.spBeforeTitle,beforeText:d.spBeforeText,beforeNote:d.spBeforeNote,ctaTitle:d.spCtaTitle,ctaSub:d.spCtaSub,ctaText:d.spCtaText,ctaLink:d.spCtaLink});const a=spTriples(d.spBadges);if(a.length)mm.badges=a;const b=spTriples(d.spSteps);if(b.length)mm.steps=b;const c=spTriples(d.spFeatures);if(c.length)mm.features=c;}
      if(slug==='contact'){Object.assign(mm,{kicker:d.spKicker,title:d.spTitle,sub:d.spSub,locationBadge:d.spLocationBadge,hours:d.spHours,callTitle:d.spCallTitle,callNote:d.spCallNote,emailTitle:d.spEmailTitle,emailNote:d.spEmailNote,whatsappTitle:d.spWhatsappTitle,whatsappText:d.spWhatsappText,whatsappNote:d.spWhatsappNote,nurseryTitle:d.spNurseryTitle,nurseryNote:d.spNurseryNote,formTitle:d.spFormTitle,formSub:d.spFormSub,formPlaceholder:d.spFormPlaceholder,securityNote:d.spSecurityNote,helpTitle:d.spHelpTitle,ctaTitle:d.spCtaTitle,ctaSub:d.spCtaSub,ctaText:d.spCtaText,ctaLink:d.spCtaLink,asideTitle:d.spAsideTitle,asideText:d.spAsideText});const h=spTriples(d.spHelp);if(h.length)mm.help=h;}
      obj.meta=mm;
    } else if(p.meta)obj.meta=p.meta;
    if(d.id)Object.assign(DB.pages.find(x=>x.id===d.id),obj);else DB.pages.push(obj);save();closeLayer();paint();toast('Page saved');};
}

/* Storefront overrides use the exact existing class names/layout, only content source changes. */
function viewStoryPage(p){
  setGreenOceanPageSEO('story'); ensureGreenOceanSchema(); const m=specialPageMeta(p),paras=(p.body||'').split(/\n\s*\n/).map(x=>x.trim()).filter(Boolean),cats=DB.categories.filter(c=>c&&c.name&&c.active!==false).slice(0,3),catImgs=['cat_indoor','cat_flowering','cat_planters'];
  return header('story')+`<main class="story-premium"><div class="story-shell"><section class="story-hero-v2"><div class="story-hero-copy"><span class="story-kicker">${ic('leaf',13)} ${esc(m.kicker)}</span><h1>${esc(m.title)}</h1><p>${esc(m.sub)}</p><div class="story-hero-actions"><a class="btn btn-primary" href="${esc(m.primaryLink)}">${esc(m.primaryText)} ${ic('arrow',13)}</a><a class="btn btn-line" href="${esc(m.secondaryLink)}">${esc(m.secondaryText)}</a></div><div class="story-hero-facts">${m.facts.map(x=>`<span>${ic(x[0]||'leaf',13)} ${esc(x[1])}</span>`).join('')}</div></div><div class="story-hero-media"><img src="${src('img:hero')}" alt="Green Ocean nursery plants in Dhanbad"><div class="story-hero-note"><span class="ico">${ic('leaf',19)}</span><span><b>${esc(m.noteTitle)}</b><small>${esc(m.noteText)}</small></span></div></div></section>
  <section class="story-trust-v2" aria-label="Green Ocean highlights">${m.trust.map(x=>`<div class="story-trust-item"><span class="ti">${ic(x[0]||'leaf',17)}</span><span><b>${esc(x[1])}</b><small>${esc(x[2]||'')}</small></span></div>`).join('')}</section>
  <section class="story-intro-v2"><article class="story-content-card"><div class="story-section-label">${esc(m.introLabel)}</div><h2>${esc(m.introTitle)}</h2><p>${esc(paras[0]||'Green Ocean began with a simple idea: make healthy plants easier to discover and buy with confidence.')}</p>${paras[1]?`<p>${esc(paras[1])}</p>`:''}<p>${esc(m.introExtra)}</p></article><div class="story-image-stack" aria-label="Green Ocean plant collection"><div class="story-image-tile big"><img src="${src('img:hero')}" alt="Healthy indoor plants from Green Ocean"><span>Healthy greens for homes, workspaces and gifting.</span></div><div class="story-image-tile"><img src="${src('img:content1')}" alt="Green Ocean plants and gardening"><span>Plant shopping with useful care context.</span></div><div class="story-image-tile"><img src="${src('img:content4')}" alt="Plant care and nursery experience"><span>Support that continues after delivery.</span></div></div></section>
  <div class="story-section-head"><div><div class="story-section-label">${esc(m.journeyLabel)}</div><h2>${esc(m.journeyTitle)}</h2><p>${esc(m.journeySub)}</p></div></div><section class="story-steps-v2">${m.steps.map((x,i)=>`<article class="story-step-v2" data-step="${String(i+1).padStart(2,'0')}"><span class="si">${ic(x[0]||'leaf',17)}</span><b>${esc(x[1])}</b><p>${esc(x[2]||'')}</p></article>`).join('')}</section>
  <div class="story-section-head"><div><div class="story-section-label">${esc(m.valuesLabel)}</div><h2>${esc(m.valuesTitle)}</h2></div></div><section class="story-values-v2">${m.values.map(x=>`<article class="story-value-v2"><span class="vi">${ic(x[0]||'leaf',18)}</span><b>${esc(x[1])}</b><p>${esc(x[2]||'')}</p></article>`).join('')}</section>
  <div class="story-section-head"><div><div class="story-section-label">${esc(m.exploreLabel)}</div><h2>${esc(m.exploreTitle)}</h2><p>${esc(m.exploreSub)}</p></div><a href="#/shop">${esc(m.exploreLinkText)}</a></div><section class="story-categories-v2">${cats.map((c,i)=>`<a class="story-category-v2" href="#/shop?cat=${encodeURIComponent(c.id)}"><img src="${src('img:'+catImgs[i])}" alt="${esc(c.name)} from Green Ocean"><span><b>${esc(c.name)}</b><small>${esc(c.desc||'Explore this Green Ocean collection')}</small></span></a>`).join('')}</section>
  <section class="story-founder-note"><blockquote>“${esc(m.quote)}”<small>${esc(m.quoteBy)}</small></blockquote><span class="story-founder-mark">${ic('leaf',30)}</span></section><section class="story-bottom-v2"><div><h3>${esc(m.bottomTitle)}</h3><p>${esc(m.bottomSub)}</p></div><div class="story-bottom-actions"><a class="btn btn-primary" href="${esc(m.bottomPrimaryLink)}">${esc(m.bottomPrimaryText)}</a><a class="btn btn-line" href="${esc(m.bottomSecondaryLink)}">${esc(m.bottomSecondaryText)}</a></div></section></div></main>`+footer();
}
