  let ni=null;$('#gFile').onchange=e=>{const f=e.target.files[0];if(!f)return;fitImage(f,1200,800,u=>{ni=u;toast('Photo ready — press save');});};$('#gSave').onclick=async()=>{const f=$('#gForm');if(!validateForm(f))return;const btn=$('#gSave'),label=btn.textContent,d=Object.fromEntries(new FormData(f).entries());btn.disabled=true;btn.textContent=ni?'Uploading…':'Saving…';try{const img=ni?await storeImageValue(ni,b.img||''):(b.img||'');const obj={id:d.id||uid('g'),title:d.title,excerpt:d.excerpt,body:d.body,active:!!d.active,featured:!!d.featured,date:d.date||b.date||today(),seoTitle:(d.seoTitle||'').trim(),seoDesc:(d.seoDesc||'').trim(),art:b.art||'bush',img};if(obj.featured)DB.blogs.forEach(x=>x.featured=false);if(d.id)Object.assign(DB.blogs.find(x=>x.id===d.id),obj);else DB.blogs.unshift(obj);save();closeLayer();paint();toast('Post saved');}catch(e){btn.disabled=false;btn.textContent=label;toast(e.message||'Cover upload failed',true);}};
