/* 900 x 900 review image helper, while keeping the Worker payload limit safe. */
function readReviewImage(file,done){
  if(!file||!/^image\//.test(file.type)){toast('Please choose a photo file',true);return;}const fr=new FileReader();fr.onload=()=>{const img=new Image();img.onload=()=>{const size=900,cv=document.createElement('canvas');cv.width=size;cv.height=size;const cx=cv.getContext('2d');cx.fillStyle='#fff';cx.fillRect(0,0,size,size);const sc=Math.max(size/img.width,size/img.height),iw=img.width*sc,ih=img.height*sc;cx.drawImage(img,(size-iw)/2,(size-ih)/2,iw,ih);let q=.72,out=cv.toDataURL('image/jpeg',q);while(out.length>155000&&q>.34){q-=.08;out=cv.toDataURL('image/jpeg',q);}if(out.length>155000){toast('Photo is too detailed for the review upload. Please choose a simpler image.',true);return;}done(out);};img.onerror=()=>toast('That photo could not be read',true);img.src=fr.result;};fr.readAsDataURL(file);
}

/* Supabase Auth users are loaded through the Worker only when the optional server secret exists. */
API.authUsers=API.authUsers||[];API.authAdminAvailable=API.authAdminAvailable??null;API.authAdminNote=API.authAdminNote||'';API.authAt=API.authAt||0;API.newsletterDraft=API.newsletterDraft||{subject:'',body:''};API.newsletterCampaigns=API.newsletterCampaigns||[];API.newsAt=API.newsAt||0;
function mergeAuthCustomers(){
  const auth=API.authUsers||[],hidden=new Set((DB.hiddenCustomers||[]).map(x=>String(x).toLowerCase())),map=new Map((DB.customers||[]).map(c=>[(c.email||'').toLowerCase(),c]));
  auth.forEach(u=>{const email=String(u.email||'').toLowerCase();if(!email||hidden.has(email))return;let c=map.get(email);if(!c){c={id:'auth_'+u.id,name:u.name||email.split('@')[0],email,phone:u.phone||'',city:'',orders:0,spent:0,joined:(u.createdAt||'').slice(0,10)||today(),registered:true,accountId:u.id};DB.customers.push(c);map.set(email,c);}Object.assign(c,{registered:true,accountId:u.id,blocked:!!u.blocked,provider:u.provider||c.provider||'email',lastSignInAt:u.lastSignInAt||''});});
  DB.customers.sort((a,b)=>(b.spent||0)-(a.spent||0));
}
const _baseLoadInbox=loadInbox;
loadInbox=async function(force){await _baseLoadInbox(force);if(!API.on||!API.key||!DB.admin)return;const now=Date.now();if(force||now-API.authAt>60000){API.authAt=now;try{const r=await API.call('/api/admin/auth-users',{admin:true,timeout:20000});if(r.ok){API.authUsers=r.users||[];API.authAdminAvailable=true;API.authAdminNote='';mergeAuthCustomers();}else{API.authAdminAvailable=false;API.authAdminNote=r.error||'Supabase Auth admin access is not configured.';}}catch(e){API.authAdminAvailable=false;API.authAdminNote='Could not load Supabase Auth users.';}}if(API.authUsers&&API.authUsers.length)mergeAuthCustomers();if(force||now-API.newsAt>30000){API.newsAt=now;try{const n=await API.call('/api/admin/newsletter',{admin:true,timeout:15000});if(n.ok){API.newsletterDraft=n.draft||{subject:'',body:''};API.newsletterCampaigns=n.campaigns||[];}}catch(e){}}save();if(appPath().startsWith('/admin/customers')||appPath().startsWith('/admin/newsletter'))softRepaint();};

function admCustomers(){
  const visible=DB.customers||[],registered=visible.filter(c=>c.registered||(DB.registeredEmails||[]).includes((c.email||'').toLowerCase())).length,blocked=visible.filter(c=>c.blocked).length,repeat=visible.filter(c=>(+c.orders||0)>1).length,spend=visible.reduce((n,c)=>n+(+c.spent||0),0);
  return adminShell('customers',`${API.authAdminAvailable===false?`<div class="media-guide-note"><b>Supabase Auth management is not active:</b> ${esc(API.authAdminNote||'Add SUPABASE_SERVICE_ROLE_KEY as a Cloudflare Worker secret.')} Order-derived customers still work normally.</div>`:''}<div class="customer-summary"><div class="admin-mini-stat"><span class="msi">${ic('users',16)}</span><span><small>Customers</small><b>${visible.length}</b></span></div><div class="admin-mini-stat"><span class="msi">${ic('check',16)}</span><span><small>Registered</small><b>${registered}</b></span></div><div class="admin-mini-stat"><span class="msi">${ic('lock',16)}</span><span><small>Blocked</small><b>${blocked}</b></span></div><div class="admin-mini-stat"><span class="msi">${ic('wallet',16)}</span><span><small>Customer value</small><b>${money(spend)}</b></span></div></div><div class="panel"><div class="scroll-x"><table class="tbl"><thead><tr><th>Customer</th><th>Contact</th><th>City</th><th>Account</th><th>Orders</th><th>Spent</th><th>Joined</th><th>Actions</th></tr></thead><tbody>${visible.map(c=>{const initials=(c.name||c.email||'C').split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase(),reg=!!c.registered||(DB.registeredEmails||[]).includes((c.email||'').toLowerCase());return `<tr><td><div class="customer-name"><span class="customer-avatar">${esc(initials)}</span><span><b>${esc(c.name||'Customer')}</b><small>${(+c.orders||0)>1?'Returning customer':(reg?'Registered customer':'Customer')}</small></span></div></td><td>${esc(c.email)}<br><small style="color:var(--muted)">${esc(c.phone||'')}</small></td><td>${esc(c.city)||'—'}</td><td>${reg?`<span class="pill ${c.blocked?'red':'green'}">${c.blocked?'Blocked':'Registered'}</span>`:'<span class="pill grey">Guest</span>'}</td><td>${c.orders||0}</td><td><b>${money(c.spent||0)}</b></td><td>${esc(c.joined||'—')}</td><td><div class="customer-actions"><button class="btn btn-sm btn-line btn-sq" data-view-cust="${esc(c.id)}">View</button>${c.accountId&&API.authAdminAvailable?`<button class="btn btn-sm ${c.blocked?'btn-soft':'btn-line'} btn-sq" data-auth-action="${c.blocked?'unblock':'block'}" data-user-id="${esc(c.accountId)}" data-email="${esc(c.email)}">${c.blocked?'Unblock':'Block'}</button><button class="btn btn-sm btn-danger btn-sq" data-auth-action="delete" data-user-id="${esc(c.accountId)}" data-email="${esc(c.email)}">Delete login</button>`:''}<button class="btn btn-sm btn-line customer-delete" data-del-cust="${esc(c.id)}" aria-label="Remove customer">${ic('trash',14)}</button></div></td></tr>`}).join('')||'<tr><td colspan="8"><div class="empty">No customers yet.</div></td></tr>'}</tbody></table></div><p style="margin:12px 0 0;color:var(--adm-muted);font-size:10.5px">“Delete login” deletes only the Supabase sign-in account after confirmation. Historical orders remain. “Remove” hides the customer from this Admin list without deleting orders.</p></div>`, 'Customers',`${visible.length} customers · ${registered} registered · ${repeat} returning`);
}

function admNewsletter(){
  const d=API.newsletterDraft||{subject:'',body:''},hist=API.newsletterCampaigns||[];
  return adminShell('newsletter',`<div class="two"><div class="panel"><div class="card-h"><h3>Subscribers</h3><span class="pill green">${DB.subscribers.length}</span></div><div class="scroll-x"><table class="tbl"><thead><tr><th>Email</th><th>Joined</th><th></th></tr></thead><tbody>${DB.subscribers.map(s=>`<tr><td>${esc(s.email)}</td><td>${esc(s.date)}</td><td><button class="btn btn-sm btn-danger btn-sq" data-del-sub="${s.id}">${ic('trash',13)}</button></td></tr>`).join('')||'<tr><td colspan="3"><div class="empty">No one has subscribed yet.</div></td></tr>'}</tbody></table></div><button class="btn btn-line btn-sq btn-block" data-act="exportSubs" style="margin-top:10px">Export emails</button></div><div class="panel"><div class="card-h"><h3>Write a campaign</h3><span class="pill ${API.on?'green':'grey'}">${API.on?'Backend connected':'Preview'}</span></div><form data-act="campaign"><div class="field"><label>Subject</label><input class="inp" name="subject" required value="${esc(d.subject||'')}" placeholder="New arrivals this week"></div><div class="field"><label>Message</label><textarea class="inp" name="body" required style="min-height:170px" placeholder="Write something short and useful.">${esc(d.body||'')}</textarea></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn btn-line btn-sq" type="submit" name="mode" value="draft">Save draft</button><button class="btn btn-primary btn-sq" type="submit" name="mode" value="send" ${!API.on||!DB.subscribers.length?'disabled':''}>Send to ${DB.subscribers.length} subscriber${DB.subscribers.length===1?'':'s'}</button></div></form><p style="font-size:11.5px;color:var(--muted);margin-top:10px">Campaign sending uses the existing server-side BREVO_API_KEY. The key is never exposed in browser code.</p></div></div><div class="panel" style="margin-top:14px"><div class="card-h"><h3>Recent campaigns</h3></div>${hist.length?hist.map(x=>`<div class="orow"><span style="flex:1"><b>${esc(x.subject)}</b><small style="display:block;color:var(--muted)">${esc(x.createdAt||'')}</small></span><span class="pill ${x.status==='Sent'?'green':x.status==='Failed'?'red':'amber'}">${esc(x.status||'Queued')}</span><small>${x.sent||0}/${x.recipients||0} sent</small></div>`).join(''):'<div class="empty">No campaigns sent yet.</div>'}</div>`, 'Newsletter','Subscribers, drafts and email campaigns from one place.');
}

/* Capture only our newly connected actions before the legacy generic handlers. */
document.addEventListener('submit',async e=>{const f=e.target;if(!f||f.dataset.act!=='campaign')return;e.preventDefault();e.stopImmediatePropagation();if(!validateForm(f))return;const d=Object.fromEntries(new FormData(f).entries()),mode=(e.submitter&&e.submitter.value)||'draft';if(!API.on){toast('Open the live Admin panel to save or send campaigns.',true);return;}if(mode==='send'){if(!DB.subscribers.length){toast('There are no subscribers to send to.',true);return;}if(!confirm(`Send this campaign to ${DB.subscribers.length} subscriber${DB.subscribers.length===1?'':'s'}?`))return;const r=await API.call('/api/admin/newsletter/send',{method:'POST',admin:true,body:{subject:d.subject,body:d.body},timeout:20000});if(!r.ok){toast(r.error,true);return;}API.newsletterDraft={subject:'',body:''};toast('Campaign queued for sending');await loadInbox(true);return;}const r=await API.call('/api/admin/newsletter/draft',{method:'PUT',admin:true,body:{subject:d.subject,body:d.body}});if(!r.ok){toast(r.error,true);return;}API.newsletterDraft={subject:d.subject,body:d.body};toast('Campaign draft saved');},true);

document.addEventListener('click',async e=>{const t=e.target.closest&&e.target.closest('[data-auth-action]');if(!t)return;e.preventDefault();e.stopImmediatePropagation();const action=t.dataset.authAction,id=t.dataset.userId,email=t.dataset.email||'this customer';if(!id)return;const msg=action==='delete'?`Delete the Supabase sign-in account for ${email}? Historical orders will be kept.`:`${action==='block'?'Block':'Unblock'} sign-in for ${email}?`;if(!confirm(msg))return;t.disabled=true;const r=await API.call('/api/admin/customers/'+action,{method:'POST',admin:true,body:{id,email},timeout:20000});t.disabled=false;if(!r.ok){toast(r.error,true);return;}toast(action==='delete'?'Login account deleted':action==='block'?'Customer sign-in blocked':'Customer sign-in restored');API.authAt=0;await loadInbox(true);},true);

/* Guard core connections: built-in designed pages cannot be deleted accidentally, and categories in use must be reassigned first. */
document.addEventListener('click',e=>{
  const pg=e.target.closest&&e.target.closest('[data-del-page]');
  if(pg){const p=DB.pages.find(x=>x.id===pg.dataset.delPage);if(p&&['story','returns','contact','faq','shipping','privacy','terms'].includes(p.slug)){e.preventDefault();e.stopImmediatePropagation();toast('This built-in page is connected to website navigation and cannot be deleted. You can edit or hide it instead.',true);return;}}
  const ct=e.target.closest&&e.target.closest('[data-del-cat]');if(!ct)return;const c=cat(ct.dataset.delCat);if(!c)return;const used=DB.products.filter(p=>p.cat===c.id);if(!used.length)return;
  e.preventDefault();e.stopImmediatePropagation();const alternatives=DB.categories.filter(x=>x.id!==c.id);if(!alternatives.length){toast('Add another category before deleting this one, because products still use it.',true);return;}
  openModal('Delete category safely',`<p style="margin:0 0 12px;color:var(--muted)"><b>${esc(c.name)}</b> is used by ${used.length} product${used.length===1?'':'s'}. Choose where those products should move before deleting the category.</p><div class="field"><label>Move products to</label><select class="inp" id="catReassign">${alternatives.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select></div>`,`<button class="btn btn-line btn-sq" data-close="1">Cancel</button><button class="btn btn-danger btn-sq" id="catDeleteSafe">Reassign & delete</button>`);
  $('#catDeleteSafe').onclick=()=>{const to=$('#catReassign').value;DB.products.forEach(p=>{if(p.cat===c.id)p.cat=to;});DB.categories=DB.categories.filter(x=>x.id!==c.id);save();closeLayer();paint();toast('Products reassigned and category deleted');};
},true);
